// CDL3LINESTRIKELookback returns how many leading bars [Core.CDL3LINESTRIKE]
// consumes before its first value: called with startIdx 0, its first value is
// at that bar.
func (c *Core) CDL3LINESTRIKELookback() (int, error) {
	lookback := c.cdl3linestrikeLookback()
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

// CDL3LINESTRIKEDisplayShift returns how many bars ahead (positive) or behind
// (negative) of the bar that computed it a chart draws output outputIdx of
// [Core.CDL3LINESTRIKE]. The values are never shifted.
//
// Every output of this function is drawn at its own bar, so the answer is 0.
//
// It takes the output's position among the outputs of [Core.CDL3LINESTRIKE],
// from 0, and returns [BadParam] for an index that names no output.
func (c *Core) CDL3LINESTRIKEDisplayShift(outputIdx int) (int, error) {
	if outputIdx < 0 || outputIdx >= 1 {
		return 0, BadParam
	}
	return 0, nil
}

// CDL3LINESTRIKE recognizes the Three-Line Strike pattern over bars startIdx
// through endIdx.
//
// A four-candle pattern: three same-color candles with consecutively higher (or
// lower) closes, each opening within or near the prior real body, then a fourth
// opposite-color candle that opens beyond the third close and closes past the
// first candle's open. TA-Lib emits a signed continuation-style signal keyed to
// the color of the first three candles, traditionally read as significant only
// inside a trend matching those three candles.
//
// Formula and more info at https://ta-lib.org/functions/cdl3linestrike.
//
// Inputs, each at least endIdx+1 long:
//   - inOpen: Open price of each bar.
//   - inHigh: High price of each bar.
//   - inLow: Low price of each bar.
//   - inClose: Close price of each bar.
//
// Outputs, each at least as long as the values written (the input length always
// suffices):
//   - outInteger: +100 for a white (rising) three-line strike, -100 for a black
//     (falling) three-line strike, 0 otherwise. Sign is the color of the first
//     three candles: candlecolor(i-1)*100.
//
// Element k of each output is the value at bar BegIdx+k of the returned
// [OutRange], and BegIdx is at least [Core.CDL3LINESTRIKELookback]: a range
// that ends before it returns NBElement 0.
//
// The error is [OutOfRangeStartIndex] or [OutOfRangeEndIndex] for a range
// outside 0 to [IndexMax] or ending before it starts, and [BadParam] for an
// input too short or an output empty or too short.
func (c *Core) CDL3LINESTRIKE(startIdx, endIdx int, inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (OutRange, error) {
	if startIdx < 0 || startIdx > IndexMax {
		return OutRange{}, OutOfRangeStartIndex
	}
	if endIdx < 0 || endIdx > IndexMax || endIdx < startIdx {
		return OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdl3linestrikeLookback())
	if lookback < 0 {
		return OutRange{}, BadParam
	}
	if len(inOpen) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inHigh) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inLow) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inClose) < endIdx+1 {
		return OutRange{}, BadParam
	}
	outLen := requiredOut(startIdx, endIdx, lookback)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	if retCode := c.cdl3linestrikeImpl(int32(startIdx), int32(endIdx), inOpen, inHigh, inLow, inClose, &outBegIdx, &outNBElement, outInteger); retCode != Success {
		return OutRange{}, retCode
	}
	return OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}

